-- Yamaha, Suzuki, Kawasaki verified factory development facts.
-- Dated 12 Nov 2026; manufacturer sources remain tied to exact model years.
with documented(catalog_model_id,category,label,value,start_year,end_year,market,source_name,source_url,verification_basis,scope_note,source_version) as (values
(290,'engineering','Yamaha Ténéré 700 — 2019 European technical reference','{"chassis":"Lightweight adventure-touring chassis","reference":"2019 Tokyo Motor Show European specification","engine_type":"Liquid-cooled in-line two-cylinder 270-degree crank","engine_capacity_cc":689}'::jsonb,2019,NULL,'Europe-spec reference shown in Japan','Yamaha Motor — 46th Tokyo Motor Show model descriptions, 10 October 2019','https://global.yamaha-motor.com/news/2019/1010/tms.html','manufacturer_primary_source_individual_model_checked_2026_11_12','Yamaha''s 2019 European-spec Ténéré 700 reference, not Rally/World Raid and not a claim of earliest global availability.','Yamaha Motor — 46th Tokyo Motor Show model descriptions, 10 October 2019'),
(232,'model_year','Suzuki GSX-R1000 — sixth-generation 2017 model announced at INTERMOT','{"generation":"Sixth generation","model_year":"2017","engine_type":"Liquid-cooled inline four-cylinder","announcement_date":"4 October 2016","engine_capacity_cc":999.8,"factory_sales_target":"Spring 2017"}'::jsonb,2017,NULL,'Europe / North America announcement','Suzuki Global — New Overseas Motorcycle Models, 4 October 2016','https://www.globalsuzuki.com/globalnews/2016/1004.html','manufacturer_primary_source_individual_model_checked_2026_11_12','Manufacturer introduction of sixth-generation GSX-R1000; not claimed to describe earlier GSX-R1000 generations or the R variant''s equipment.','Suzuki Global — New Overseas Motorcycle Models, 4 October 2016'),
(232,'engineering','Suzuki GSX-R1000 — 2017 European specification and engine development','{"power":"148.6 kW at 13,200 rpm","torque":"117.6 Nm at 10,800 rpm","weight":"200 kg (manufacturer European non-ABS reference)","development":"Broad Power System with intake variable valve timing","engine_capacity_cc":999.8}'::jsonb,2017,NULL,'Europe-spec 2017 GSX-R1000','Suzuki Global — New Overseas Motorcycle Models, 4 October 2016','https://www.globalsuzuki.com/globalnews/2016/1004.html','manufacturer_primary_source_individual_model_checked_2026_11_12','Suzuki press release lists 200kg GSX-R1000, 202kg ABS version, 203kg GSX-R1000R. This record only represents the non-ABS GSX-R1000 European variant; not transferable to R or future years.','Suzuki Global — New Overseas Motorcycle Models, 4 October 2016'),
(204,'market_launch','Kawasaki Z900RS — 2017 Japanese introduction','{"engine":"Liquid-cooled inline four-cylinder","model_year":"2018 Japan presentation","factory_design_reference":"Z1 (900 Super Four)","japan_planned_sales_date":"1 December 2017"}'::jsonb,2017,NULL,'Japan','Kawasaki Heavy Industries — Tokyo Motor Show 2017 announcement','https://global.kawasaki.com/en/corp/newsroom/news/detail/?f=20171025_6255','manufacturer_primary_source_individual_model_checked_2026_11_12','Kawasaki announced 1 Dec 2017 Japanese release; 2017 is announcement/retail date, not a universal first model year or standard Z900 launch.','Kawasaki Heavy Industries — Tokyo Motor Show 2017 announcement'),
(963,'model_year','Suzuki GSX-S750 — 2017 redesign and European-market launch','{"position":"750-class street sport motorcycle","model_year":"2017","model_family":"GSX-S","planned_sales":"Spring 2017","factory_announcement":"4 October 2016"}'::jsonb,2017,NULL,'Europe / North America','Suzuki Global — INTERMOT 2016 motorcycle introductions','https://www.globalsuzuki.com/globalnews/2016/1004.html','manufacturer_primary_source_individual_model_checked_2026_11_12','2017 GSX-S750 redesign only, distinct from GSX-S1000 and from earlier GSX-S750 generations.','Suzuki Global — INTERMOT 2016 motorcycle introductions')
),
new_facts as (
 insert into public.motorcycle_catalog_facts(catalog_model_id,category,label,value,start_year,end_year,market,source_name,source_url,verification_status)
 select d.catalog_model_id,d.category,d.label,d.value,d.start_year,d.end_year,d.market,d.source_name,d.source_url,'verified'
 from documented d
 where exists(select 1 from public.motorcycle_catalog_dropdown_clean m where m.model_id=d.catalog_model_id)
 and not exists(select 1 from public.motorcycle_catalog_facts f where f.catalog_model_id=d.catalog_model_id and f.label=d.label and f.source_url=d.source_url)
 returning id
)
insert into public.motorcycle_catalog_fact_verification_audit(fact_id,checked_at,verification_basis,source_url,scope_note,source_version)
select f.id,now(),d.verification_basis,d.source_url,d.scope_note,d.source_version
from documented d join public.motorcycle_catalog_facts f
on f.catalog_model_id=d.catalog_model_id and f.label=d.label and f.source_url=d.source_url
where not exists(select 1 from public.motorcycle_catalog_fact_verification_audit a where a.fact_id=f.id);
